// Prepara el texto de la factura para la extraccion.
const salida = [];
for (const item of $input.all()) {
  const j = item.json;
  const asunto = j.subject || j.Subject || '';
  const cuerpo = j.text || j.snippet || '';
  salida.push({
    json: {
      id: $execution.id + '-' + $itemIndex,
      fecha_recepcion: new Date().toISOString(),
      remitente: j.from?.value?.[0]?.address || j.From || '',
      texto_factura: ('Asunto: ' + asunto + '\n\n' + cuerpo).slice(0, 8000),
      estado: 'recibida',
    },
  });
}
return salida;

