// Junta el correo con la extraccion y hace la comprobacion aritmetica en codigo:
// las cuentas no se le piden al modelo.
const salida = [];
for (const item of $input.all()) {
  const correo = $('Preparar texto de la factura').first().json;
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let datos;
  try {
    datos = JSON.parse(bruto);
  } catch (error) {
    datos = { proveedor: null, numero_factura: null, base: null, iva: null, total: null, iban: null, vencimiento: null, concepto: null, dudas: ['extraccion no parseable: ' + bruto.slice(0, 150)] };
  }
  const dudas = Array.isArray(datos.dudas) ? datos.dudas : [];
  const base = Number(datos.base);
  const iva = Number(datos.iva);
  const total = Number(datos.total);
  if (!Number.isNaN(base) && !Number.isNaN(iva) && !Number.isNaN(total)) {
    if (Math.abs(base + iva - total) > 0.01) {
      dudas.push('DESCUADRE: base ' + base + ' + iva ' + iva + ' = ' + (base + iva).toFixed(2) + ', pero total ' + total);
    }
  }
  salida.push({
    json: {
      id: correo.id,
      fecha_recepcion: correo.fecha_recepcion,
      remitente: correo.remitente,
      proveedor: datos.proveedor ?? '',
      cif: datos.cif ?? '',
      numero_factura: datos.numero_factura ?? '',
      fecha_factura: datos.fecha_factura ?? '',
      base: datos.base ?? '',
      iva: datos.iva ?? '',
      total: datos.total ?? '',
      iban: datos.iban ?? '',
      vencimiento: datos.vencimiento ?? '',
      concepto: datos.concepto ?? '',
      dudas: dudas.join(' | '),
      estado: 'extraida',
    },
  });
}
return salida;

