// Filtra las facturas vencidas a las que toca recordatorio segun la politica.
// DIAS_NIVEL_1: dias tras el vencimiento para el primer recordatorio.
const DIAS_NIVEL_1 = 3;
const DIAS_NIVEL_2 = 15;
const DIAS_NIVEL_3 = 30;
const hoy = new Date();
const salida = [];
for (const item of $input.all()) {
  const f = item.json;
  const estado = String(f.estado || '');
  if (!['pendiente', 'vencida', 'recordada_1', 'recordada_2'].includes(estado)) continue;
  if (!f.vencimiento) continue;
  const dias = Math.floor((hoy - new Date(String(f.vencimiento))) / 86400000);
  let nivel = null;
  if (estado === 'pendiente' || estado === 'vencida') {
    if (dias >= DIAS_NIVEL_1) nivel = 1;
  } else if (estado === 'recordada_1' && dias >= DIAS_NIVEL_2) {
    nivel = 2;
  } else if (estado === 'recordada_2' && dias >= DIAS_NIVEL_3) {
    nivel = 3;
  }
  if (!nivel) continue;
  salida.push({
    json: {
      numero: f.numero,
      cliente: f.cliente,
      email_cliente: f.email_cliente,
      total: f.total,
      vencimiento: f.vencimiento,
      dias_vencida: dias,
      nivel,
      texto_propuesto:
        nivel === 1
          ? 'Hola, te escribo por la factura ' + f.numero + ' (' + f.total + ' EUR), que vencio el ' + f.vencimiento + '. Seguramente se haya traspapelado: te la reenvio encantado si hace falta. Cualquier cosa que necesites para tramitarla, me dices. Un saludo.'
          : nivel === 2
            ? 'Hola, te recuerdo la factura ' + f.numero + ' (' + f.total + ' EUR), vencida el ' + f.vencimiento + ' y sobre la que te escribi hace unos dias. Te pido una fecha concreta de pago esta semana. Gracias.'
            : 'Hola, la factura ' + f.numero + ' (' + f.total + ' EUR) sigue pendiente ' + dias + ' dias despues de su vencimiento y tras dos recordatorios. Segun nuestras condiciones, pausamos nuevos trabajos hasta regularizarla. Quedo a tu disposicion para resolverlo hoy mismo.',
    },
  });
}
return salida;

